'use client'

import { useEffect, useState } from 'react'
import { useParams, usePathname } from 'next/navigation'
import Link from 'next/link'
import Image from 'next/image'
import { useAuth } from '@/contexts/AuthContext'
import { useBrand } from '@/hooks/useBrand'
import {
    Home, FileText, Image as ImageIcon, Settings,
    ChevronLeft, Loader2, Menu, X
} from 'lucide-react'

// ============================================
// TYPES
// ============================================

interface AdminLayoutWrapperProps {
    children: React.ReactNode
}

// ============================================
// COMPONENT
// ============================================

export default function AdminLayoutWrapper({ children }: AdminLayoutWrapperProps) {
    const params = useParams()
    const pathname = usePathname()
    const brandId = params?.id as string

    const { user, loading: authLoading } = useAuth()
    const { brand, loading: brandLoading } = useBrand(brandId || '')

    const [sidebarOpen, setSidebarOpen] = useState(false)

    // Determine current page type
    const isBuilderPage = pathname?.includes('/admin/brand/') &&
        !pathname?.includes('/assets') &&
        !pathname?.includes('/settings') &&
        !pathname?.includes('/pages')

    // Loading state
    if (authLoading || (brandId && brandLoading)) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50">
                <Loader2 className="w-8 h-8 animate-spin text-gray-400" />
            </div>
        )
    }

    // No brand ID means we're on the dashboard
    if (!brandId) {
        return <>{children}</>
    }

    return (
        <div className="flex min-h-screen bg-gray-50">
            {/* Mobile menu button */}
            <button
                onClick={() => setSidebarOpen(!sidebarOpen)}
                className="md:hidden fixed top-4 left-4 z-50 p-2 bg-white rounded-lg shadow-md"
            >
                {sidebarOpen ? <X size={20} /> : <Menu size={20} />}
            </button>

            {/* Sidebar - Hidden on builder pages, shown for settings/assets/pages */}
            {!isBuilderPage && (
                <aside className={`
                    fixed top-0 left-0 bottom-0 w-64 bg-white border-r border-gray-100 z-40
                    transition-transform duration-200
                    ${sidebarOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
                `}>
                    <div className="flex flex-col h-full">
                        {/* Header */}
                        <div className="p-4 border-b border-gray-100">
                            <Link href="/admin" className="flex items-center gap-2 text-gray-600 hover:text-gray-900 text-sm mb-4">
                                <ChevronLeft size={16} />
                                Back to Dashboard
                            </Link>
                            {brand && (
                                <div className="flex items-center gap-3">
                                    <div
                                        className="w-10 h-10 rounded-lg flex items-center justify-center text-white font-bold"
                                        style={{ backgroundColor: brand.primary_color || '#0066FF' }}
                                    >
                                        {brand.name.charAt(0)}
                                    </div>
                                    <div>
                                        <h2 className="font-semibold text-gray-900">{brand.name}</h2>
                                        <p className="text-xs text-gray-400">Brand Settings</p>
                                    </div>
                                </div>
                            )}
                        </div>

                        {/* Navigation */}
                        <nav className="flex-1 p-4 space-y-1">
                            <NavItem
                                href={`/admin/brand/${brandId}/introduction`}
                                icon={Home}
                                label="Editor"
                                active={isBuilderPage}
                            />
                            <NavItem
                                href={`/admin/brand/${brandId}/assets`}
                                icon={ImageIcon}
                                label="Assets"
                                active={pathname?.includes('/assets')}
                            />
                            <NavItem
                                href={`/admin/brand/${brandId}/pages`}
                                icon={FileText}
                                label="Pages"
                                active={pathname?.includes('/pages')}
                            />
                            <NavItem
                                href={`/admin/brand/${brandId}/settings`}
                                icon={Settings}
                                label="Settings"
                                active={pathname?.includes('/settings')}
                            />
                        </nav>

                        {/* User */}
                        <div className="p-4 border-t border-gray-100">
                            <div className="flex items-center gap-3">
                                <div className="w-8 h-8 rounded-full bg-gradient-to-tr from-purple-500 to-pink-500 flex items-center justify-center text-white text-sm font-medium">
                                    {user?.email?.charAt(0)?.toUpperCase() || 'U'}
                                </div>
                                <div className="flex-1 min-w-0">
                                    <p className="text-sm font-medium text-gray-900 truncate">{user?.email}</p>
                                </div>
                            </div>
                        </div>
                    </div>
                </aside>
            )}

            {/* Main content */}
            <main className={!isBuilderPage ? 'flex-1 md:ml-64' : 'flex-1'}>
                {children}
            </main>

            {/* Mobile overlay */}
            {sidebarOpen && !isBuilderPage && (
                <div
                    className="fixed inset-0 bg-black/50 z-30 md:hidden"
                    onClick={() => setSidebarOpen(false)}
                />
            )}
        </div>
    )
}

// ============================================
// SUB-COMPONENTS
// ============================================

function NavItem({
    href,
    icon: Icon,
    label,
    active
}: {
    href: string
    icon: any
    label: string
    active?: boolean
}) {
    return (
        <Link
            href={href}
            className={`
                flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium transition-colors
                ${active
                    ? 'bg-gray-100 text-gray-900'
                    : 'text-gray-600 hover:bg-gray-50 hover:text-gray-900'
                }
            `}
        >
            <Icon size={18} />
            {label}
        </Link>
    )
}
