'use client'

import { useState, useEffect, useCallback } from 'react'
import { supabase } from '@/lib/supabase'
import { useAuth } from '@/contexts/AuthContext'

// ============================================
// TYPES
// ============================================

export interface Brand {
    id: string
    workspace_id: string
    name: string
    slug: string
    logo_url: string | null
    banner_url: string | null
    primary_color: string | null
    font_family: string | null
    custom_font_url: string | null
    created_at: string
    updated_at: string
}

interface UseBrandReturn {
    brand: Brand | null
    loading: boolean
    error: string | null
    refetch: () => Promise<void>
    updateBrand: (updates: Partial<Brand>) => Promise<{ error: Error | null }>
}

// ============================================
// HOOK - Single brand by ID or slug
// ============================================

export function useBrand(identifier: string): UseBrandReturn {
    const [brand, setBrand] = useState<Brand | null>(null)
    const [loading, setLoading] = useState(true)
    const [error, setError] = useState<string | null>(null)

    const fetchBrand = useCallback(async () => {
        if (!identifier) {
            setLoading(false)
            return
        }

        setLoading(true)
        setError(null)

        try {
            // Check if identifier is UUID or slug
            const isUUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(identifier)

            const { data, error: fetchError } = await supabase
                .from('brands')
                .select('*')
                .eq(isUUID ? 'id' : 'slug', identifier)
                .single()

            if (fetchError) {
                setError(fetchError.message)
                setBrand(null)
            } else {
                setBrand(data)
            }
        } catch (err: any) {
            setError(err.message)
            setBrand(null)
        } finally {
            setLoading(false)
        }
    }, [identifier])

    useEffect(() => {
        fetchBrand()
    }, [fetchBrand])

    const updateBrand = async (updates: Partial<Brand>): Promise<{ error: Error | null }> => {
        if (!brand) {
            return { error: new Error('No brand loaded') }
        }

        try {
            const { error: updateError } = await supabase
                .from('brands')
                .update(updates)
                .eq('id', brand.id)

            if (updateError) {
                return { error: updateError }
            }

            // Refetch to get updated data
            await fetchBrand()
            return { error: null }
        } catch (err) {
            return { error: err as Error }
        }
    }

    return {
        brand,
        loading,
        error,
        refetch: fetchBrand,
        updateBrand
    }
}
